CREATE TABLE IF NOT EXISTS `xm_quality_unit_allocation` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`enter_item_id` bigint unsigned NOT NULL,`unit_no` int unsigned NOT NULL,`allocated` tinyint unsigned NOT NULL DEFAULT 0,`operator_id` bigint NOT NULL DEFAULT 0,`operator_name` varchar(64) NOT NULL DEFAULT '',`create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,`update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY (`id`),UNIQUE KEY `uk_item_unit` (`enter_item_id`,`unit_no`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='质检花材单扎配货状态';
